// sync-safewords.mjs - the stream's safeword dictionary has ONE source:
// stream-host/data/safewords.txt (read by the host agent). The signup worker
// cannot read that file at runtime, so this copies it into src/safewords-list.ts.
//
//   node tools/sync-safewords.mjs           regenerate the list
//   node tools/sync-safewords.mjs --check   exit 1 if the generated file is stale
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const SRC = join(here, "..", "..", "stream-host", "data", "safewords.txt");
const OUT = join(here, "..", "src", "safewords-list.ts");

const words = [...new Set(readFileSync(SRC, "utf8").split("\n").map((s) => s.trim().toLowerCase()).filter(Boolean))];
const bad = words.filter((w) => !/^[a-z]+$/.test(w));
if (bad.length) { console.error(`not plain lowercase words: ${bad.join(", ")}`); process.exit(2); }

const lines = [];
for (let i = 0; i < words.length; i += 8) lines.push("  " + words.slice(i, i + 8).map((w) => JSON.stringify(w)).join(", ") + ",");
const text = `// GENERATED by tools/sync-safewords.mjs from stream-host/data/safewords.txt - do not edit.
export const WORDS: string[] = [
${lines.join("\n")}
];
`;

if (process.argv.includes("--check")) {
  let cur = "";
  try { cur = readFileSync(OUT, "utf8"); } catch {}
  if (cur.replace(/\r/g, "") !== text) { console.error("src/safewords-list.ts is out of date: run node tools/sync-safewords.mjs"); process.exit(1); }
  console.log(`safewords in sync (${words.length} words)`);
} else {
  writeFileSync(OUT, text);
  console.log(`wrote ${words.length} words to src/safewords-list.ts`);
}
